const body = $input.first().json.body || $input.first().json;
const deal = body.current || body;

const dateStart = deal.dateStart || deal.date_start || '';
const dateFinish = deal.dateFinish || deal.date_finish || '';

let duracionDias = null;
if (dateStart && dateFinish) {
  const d = Math.ceil((new Date(dateFinish) - new Date(dateStart)) / 86400000);
  duracionDias = d > 0 ? d : 1;
}

// Phone from person
let phone = '';
if (deal.person_id && deal.person_id.phone) {
  const phones = Array.isArray(deal.person_id.phone) ? deal.person_id.phone : [deal.person_id.phone];
  phone = (phones.find(p => p.primary) || phones[0] || {}).value || '';
}

// Clean phone: ensure starts with +
if (phone && !phone.startsWith('+')) {
  phone = '+34' + phone.replace(/\s/g, '');
}

const personName = deal.person_id?.name || deal.person_name || 'Cliente';
const orgName = deal.org_id?.name || deal.org_name || '';

return [{
  json: {
    dealId: String(deal.id || ''),
    pipelineId: deal.pipeline_id || deal.active_flag ? 6 : 0,
    stageId: deal.stage_id || 0,
    title: deal.title || '',
    personName,
    orgName,
    phone,
    assetType: deal.assetType || deal['Tipo de Activo'] || '',
    assetWeight: deal.assetWeight || '',
    assetEngine: (deal.assetEngine || deal['Motor'] || '').toLowerCase(),
    dateStart,
    dateFinish,
    duracionDias,
    workLocation: deal.workLocation || deal['Dirección del trabajo'] || '',
    razonSocial: deal.razonSocial || deal['Razón Social'] || orgName,
    dealValue: deal.value || 0
  }
}];

const raw = $json.content?.[0]?.text || '{}';
let q;
try {
  const cleaned = raw.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  q = JSON.parse(cleaned);
} catch(e) {
  q = { can_quote: false, reason_no_quote: 'Error parsing Claude response: ' + e.message };
}

const prev = $('Extraer datos del deal').item.json;
return [{
  json: {
    ...prev,
    quote: q
  }
}];

